<h3 id="watermark-props" tabindex="-1"><a class="header-anchor" href="#watermark-props"><span><code v-pre>&lt;watermark&gt;</code> Props</span></a></h3>
<table>
<thead>
<tr>
<th>参数名</th>
<th>描述</th>
<th>类型</th>
<th style="text-align:center">默认值</th>
</tr>
</thead>
<tbody>
<tr>
<td>content</td>
<td>水印文字内容</td>
<td><code v-pre>string | string[]</code></td>
<td style="text-align:center"><code v-pre>-</code></td>
</tr>
<tr>
<td>image</td>
<td>图片源，建议使用 2 倍或 3 倍图</td>
<td><code v-pre>string</code></td>
<td style="text-align:center"><code v-pre>-</code></td>
</tr>
<tr>
<td>width</td>
<td>水印宽度（默认为内容宽度）</td>
<td><code v-pre>number</code></td>
<td style="text-align:center"><code v-pre>-</code></td>
</tr>
<tr>
<td>height</td>
<td>水印高度（默认为内容高度）</td>
<td><code v-pre>number</code></td>
<td style="text-align:center"><code v-pre>-</code></td>
</tr>
<tr>
<td>gap</td>
<td>水印间的间距</td>
<td><code v-pre>[number, number]</code></td>
<td style="text-align:center"><code v-pre>() =&gt; [90, 90]</code></td>
</tr>
<tr>
<td>offset</td>
<td>距离容器左上角的偏移量，默认为水印间距的一半</td>
<td><code v-pre>[number, number]</code></td>
<td style="text-align:center"><code v-pre>[gap[0]/2, gap[1]/2]</code></td>
</tr>
<tr>
<td>rotate</td>
<td>旋转角度</td>
<td><code v-pre>number</code></td>
<td style="text-align:center"><code v-pre>-22</code></td>
</tr>
<tr>
<td>font</td>
<td>水印字体样式，具体参数配置看 <a href="#WatermarkFont">WatermarkFont</a></td>
<td><code v-pre>WatermarkFont</code></td>
<td style="text-align:center"><code v-pre>-</code></td>
</tr>
<tr>
<td>z-index</td>
<td>水印层级</td>
<td><code v-pre>number</code></td>
<td style="text-align:center"><code v-pre>6</code></td>
</tr>
<tr>
<td>alpha</td>
<td>透明度</td>
<td><code v-pre>number</code></td>
<td style="text-align:center"><code v-pre>1</code></td>
</tr>
<tr>
<td>anti-tamper</td>
<td>水印防篡改</td>
<td><code v-pre>boolean</code></td>
<td style="text-align:center"><code v-pre>true</code></td>
</tr>
<tr>
<td>grayscale</td>
<td>灰阶水印</td>
<td><code v-pre>boolean</code></td>
<td style="text-align:center"><code v-pre>false</code></td>
</tr>
<tr>
<td>repeat</td>
<td>是否重复水印</td>
<td><code v-pre>boolean</code></td>
<td style="text-align:center"><code v-pre>true</code></td>
</tr>
<tr>
<td>staggered</td>
<td>是否错开排列</td>
<td><code v-pre>boolean</code></td>
<td style="text-align:center"><code v-pre>true</code></td>
</tr>
</tbody>
</table>
<h3 id="watermarkfont" tabindex="-1"><a class="header-anchor" href="#watermarkfont"><span>WatermarkFont</span></a></h3>
<table>
<thead>
<tr>
<th>参数名</th>
<th>描述</th>
<th>类型</th>
<th style="text-align:center">默认值</th>
</tr>
</thead>
<tbody>
<tr>
<td>color</td>
<td>字体颜色</td>
<td><code v-pre>string</code></td>
<td style="text-align:center"><code v-pre>rgba(0, 0, 0, 0.15)</code></td>
</tr>
<tr>
<td>fontSize</td>
<td>字体大小</td>
<td><code v-pre>number</code></td>
<td style="text-align:center"><code v-pre>16</code></td>
</tr>
<tr>
<td>fontFamily</td>
<td>字体类型</td>
<td><code v-pre>string</code></td>
<td style="text-align:center"><code v-pre>sans-serif</code></td>
</tr>
<tr>
<td>fontStyle</td>
<td>字体样式</td>
<td><code v-pre>'none' | 'normal' | 'italic' | 'oblique'</code></td>
<td style="text-align:center"><code v-pre>normal</code></td>
</tr>
<tr>
<td>textAlign</td>
<td>字体对齐方式</td>
<td><code v-pre>'start' | 'end' | 'left' | 'right' | 'center'</code></td>
<td style="text-align:center"><code v-pre>center</code></td>
</tr>
<tr>
<td>fontWeight</td>
<td>字体粗细</td>
<td><code v-pre>'normal' | 'bold' | 'bolder' | 'lighter' | number</code></td>
<td style="text-align:center"><code v-pre>normal</code></td>
</tr>
</tbody>
</table>
